SELECT p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, a.discharge_location, AVG(a.los) AS average_los, MEDIAN(a.los) AS median_los, PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY a.los) AS p75_los, PERCENTILE_CONT(0.90) WITHIN GROUP (ORDER BY a.los) AS p90_los, COUNT(*) filter (WHERE a.los < 5) AS short_los_count FROM patients p JOIN admissions a ON p.subject_id = a.subject_id WHERE p.gender = 'M' AND p.anchor_age BETWEEN 89 AND 99 AND a.admission_type != 'emergency' GROUP BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, a.discharge_location ORDER BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, a.discharge_location NULLS LAST;